USE [Hyperyek]; IF OBJECT_ID(N'dbo.ExternalIntegrationConnections',N'U') IS NULL BEGIN CREATE TABLE dbo.ExternalIntegrationConnections (Id bigint IDENTITY PRIMARY KEY,ShopId int NOT NULL,TenantId nvarchar(30) NOT NULL,Provider tinyint NOT NULL,DisplayName nvarchar(200) NOT NULL,AccountIdentifier nvarchar(200) NOT NULL,CredentialType tinyint NOT NULL,CredentialsJson nvarchar(max) NOT NULL,ExpiresAtUtc datetime2 NULL,IsEnabled bit NOT NULL DEFAULT(1),ConnectedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),LastSyncAtUtc datetime2 NULL,LastError nvarchar(2000) NULL,CONSTRAINT UQ_ExternalIntegrationConnections UNIQUE(ShopId,Provider,AccountIdentifier)); END; IF OBJECT_ID(N'dbo.ExternalProductMappings',N'U') IS NULL BEGIN CREATE TABLE dbo.ExternalProductMappings (Id bigint IDENTITY PRIMARY KEY,ConnectionId bigint NOT NULL,ShopId int NOT NULL,HyperProductId int NOT NULL,ExternalProductId nvarchar(200) NOT NULL,ExternalSku nvarchar(200) NULL,ExternalVariantId nvarchar(200) NULL,LastExternalPrice decimal(18,2) NULL,LastExternalInventory decimal(18,3) NULL,LastSyncAtUtc datetime2 NULL,IsActive bit NOT NULL DEFAULT(1),CONSTRAINT UQ_ExternalProductMappings UNIQUE(ConnectionId,ExternalProductId,ExternalVariantId),CONSTRAINT FK_ExternalProductMappings_Connection FOREIGN KEY(ConnectionId) REFERENCES dbo.ExternalIntegrationConnections(Id)); END; IF OBJECT_ID(N'dbo.IntegrationSyncRuns',N'U') IS NULL BEGIN CREATE TABLE dbo.IntegrationSyncRuns (Id bigint IDENTITY PRIMARY KEY,ConnectionId bigint NOT NULL,StartedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),FinishedAtUtc datetime2 NULL,Status tinyint NOT NULL,ItemsRead int NOT NULL DEFAULT(0),ItemsWritten int NOT NULL DEFAULT(0),ItemsFailed int NOT NULL DEFAULT(0),Error nvarchar(4000) NULL,CONSTRAINT FK_IntegrationSyncRuns_Connection FOREIGN KEY(ConnectionId) REFERENCES dbo.ExternalIntegrationConnections(Id)); END
